-- One-time fictional guest form for the dedicated test/demo Elmina site.
-- New live QR codes are generated by authenticated admins through existing RPCs.
DO $seed$
DECLARE s public.sites; admin_id uuid; fid uuid;
  form_fields jsonb := '[{"key":"purpose","required":true},{"key":"party_size","required":true},{"key":"safety_ack","required":true}]'::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM private.runtime_settings WHERE environment IN ('test','development') AND simulations_enabled) THEN
    RAISE EXCEPTION 'Demo form seeding requires development/test with simulated data enabled';
  END IF;
  SELECT st.* INTO STRICT s FROM public.sites st JOIN public.tenants t ON t.id=st.tenant_id
   WHERE t.demo AND t.name LIKE 'Demo Elmina %' AND st.name='Demo Elmina Community Hub';
  IF s.visitor_form_version_id IS NOT NULL THEN
    RAISE NOTICE 'Published visitor form exists; left intact';
    RETURN;
  END IF;
  IF NOT private.valid_visitor_fields(form_fields) THEN RAISE EXCEPTION 'Invalid demo form'; END IF;
  SELECT user_id INTO STRICT admin_id FROM public.memberships WHERE site_id=s.id AND role='TOWNSHIP_ADMIN' AND active LIMIT 1;
  fid:=md5('amin-v2:public-guest-form:'||s.id::text)::uuid;
  INSERT INTO public.visitor_form_versions(id,tenant_id,site_id,version,title,template,fields,published_by,publish_request_id)
    VALUES(fid,s.tenant_id,s.id,1,'Welcome to Elmina · Visitor Registration','custom',form_fields,admin_id,md5('amin-v2:guest-form-publish:'||s.id::text)::uuid)
    ON CONFLICT DO NOTHING;
  UPDATE public.sites SET visitor_form_version_id=fid WHERE id=s.id AND visitor_form_version_id IS NULL;
END $seed$;
